<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('.z4-store-artwork-authenticity'),select=form?.querySelector('[data-evidence-role]'),radios=[...form?.querySelectorAll('input[name="ownership_basis"]')||[]];if(!form)return;const sync=()=>{const basis=radios.find(r=>r.checked)?.value;[...select.options].forEach(option=>{if(!option.value)return;option.hidden=option.dataset.basis!==basis;option.disabled=option.dataset.basis!==basis});if(select.selectedOptions[0]?.disabled)select.value=''};radios.forEach(r=>r.addEventListener('change',sync));sync()});</script>
